def recherche_sequentielle(tab, valeur, taille):
    i = 0
    while i < taille:
        if tab[i] == valeur:
            return i
        i = i + 1
    return -1

def recherche_dichotomique(tab, valeur, taille):
    debut = 0
    fin = taille - 1
    while debut <= fin:
        mil = (debut + fin) // 2
        if tab[mil] == valeur:
            return mil
        elif tab[mil] < valeur:
            debut = mil + 1
        else:
            fin = mil - 1
    return -1

