def tri_selection(tab, n):
    for i in range(n - 1):
        min_idx = i
        for j in range(i + 1, n):
            if tab[j] < tab[min_idx]:
                min_idx = j
        tab[i], tab[min_idx] = tab[min_idx], tab[i]

def tri_insertion(tab, n):
