        x = tab[i]
        j = i
        while j > 0 and tab[j - 1] > x:
            tab[j] = tab[j - 1]
            j = j - 1
        tab[j] = x

def fusion(T, debut, milieu, fin, Temp):
    i = debut
    j = milieu + 1
    k = debut 
    while i <= milieu and j <= fin:
        if T[i] <= T[j]:
            Temp[k] = T[i]
            i = i + 1
        else:
            Temp[k] = T[j]
            j = j + 1
        k = k + 1
    while i <= milieu:
        Temp[k] = T[i]
        i = i + 1
        k = k + 1
    while j <= fin:
        Temp[k] = T[j]
        j = j + 1
        k = k + 1
    for i in range(debut, fin + 1):
        T[i] = Temp[i]

def tri_fusion(T, debut, fin):
    if debut < fin:
        milieu = (debut + fin) // 2
        tri_fusion(T, debut, milieu)
        tri_fusion(T, milieu + 1, fin)
        Temp = [0] * len(T)
        fusion(T, debut, milieu, fin, Temp)

def tri_rapide_recursif(T, debut, fin):
    i = debut
    j = fin
    pivot = T[(debut + fin) // 2]
    while i <= j:
        while T[i] < pivot:
            i = i + 1
        while T[j] > pivot:
            j = j - 1
        if i <= j:
            T[i], T[j] = T[j], T[i]
            i = i + 1
            j = j - 1
    if debut < j:
        tri_rapide_recursif(T, debut, j)
    if i < fin:
        tri_rapide_recursif(T, i, fin)

def tri_rapide(T, n):
    if n > 0:
        tri_rapide_recursif(T, 0, n - 1)

