def deuxieme_max(T, n):
    if n < 2:
        return -1
    if T[0] > T[1]:
        premier = T[0]
        second = T[1]
    else:
        premier = T[1]
        second = T[0]
    for i in range(2, n):
        element = T[i]
        if element > premier:
            second = premier
            premier = element
        elif element > second and element != premier:
            second = element
    return second

