def crible_eratosthene(n):
    premier = [True] * (n + 1)
    premier[0] = False
    premier[1] = False
    for i in range(2, int(math.sqrt(n)) + 1):
        if premier[i] == True:
            for j in range(i * i, n + 1, i):
                premier[j] = False
    res = []
    for i in range(2, n + 1):
        if premier[i] == True:
            res.append(i)
    return res

