def est_palindrome(s):
    gauche = 0
    droite = len(s) - 1
    while gauche < droite:
        if s[gauche].upper() != s[droite].upper():
            return False
        gauche = gauche + 1
        droite = droite - 1
    return True

def trier_chaine(s):
    lettres = list(s)
    n = len(lettres)
    for i in range(n):
        for j in range(0, n - i - 1):
            if lettres[j] > lettres[j + 1]:
                lettres[j], lettres[j + 1] = lettres[j + 1], lettres[j]
    return ''.join(lettres)

