def cesar(s, k):
    res = ""
    for c in s:
        if 'A' <= c <= 'Z':
            nouveau_code = (ord(c) - 65 + k) % 26 + 65
            res = res + chr(nouveau_code)
        elif 'a' <= c <= 'z':
            nouveau_code = (ord(c) - 97 + k) % 26 + 97
            res = res + chr(nouveau_code)
        else:
            res = res + c
    return res

def longueur_sans_rep(s):
    debut = 0
    max_len = 0
    n = len(s)
    for i in range(n):
        indice_existant = s.find(s[i], debut, i)
        if indice_existant != -1:
            debut = indice_existant + 1
        longueur_actuelle = i - debut + 1
        if longueur_actuelle > max_len:
            max_len = longueur_actuelle
    return max_len

