def levenshtein(a, b):
    m = len(a)
    n = len(b)
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            dp[i][j] = min(
                dp[i - 1][j] + 1,
                dp[i][j - 1] + 1,
                dp[i - 1][j - 1] + cost
            )
    return dp[m][n]

def sac_a_dos(poids, valeurs, n, W):
    dp = [0] * (W + 1)
    for i in range(n):
        for w in range(W, poids[i] - 1, -1):
            dp[w] = max(dp[w], dp[w - poids[i]] + valeurs[i])
    return dp[W]

def kadane(tab, n):
    max_actuel = tab[0]
    max_global = tab[0]
    for i in range(1, n):
        max_actuel = max(tab[i], max_actuel + tab[i])
        if max_actuel > max_global:
            max_global = max_actuel
    return max_global

