def plus_grand_carre_matrice(mat):
    if not mat or not mat[0]:
        return 0
    m = len(mat)
    n = len(mat[0])
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    max_cote = 0
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if mat[i-1][j-1] == 1:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_cote = max(max_cote, dp[i][j])
    return max_cote

def recherche_dichotomique(tab, val, debut, fin):
    while debut <= fin:
        mil = (debut + fin) // 2
        if tab[mil] == val:
            return mil
        elif tab[mil] < val:
            debut = mil + 1
        else:
            fin = mil - 1
    return -1

def recherche_exponentielle(tab, val):
    if not tab:
        return -1
    if tab[0] == val:
        return 0
    i = 1
    n = len(tab)
    while i < n and tab[i] <= val:
        i = i * 2
    return recherche_dichotomique(tab, val, i // 2, min(i, n - 1))

def interpolation_search(tab, val):
    lo = 0
    hi = len(tab) - 1
    while lo <= hi and tab[lo] <= val <= tab[hi]:
        if lo == hi:
            if tab[lo] == val:
                return lo
            return -1
        pos = lo + ((val - tab[lo]) * (hi - lo)) // (tab[hi] - tab[lo])
        if tab[pos] == val:
            return pos
        if tab[pos] < val:
            lo = pos + 1
        else:
            hi = pos - 1
    return -1

