def produit_matrices(A, B):
    l = len(A)
    p = len(A[0])
    c = len(B[0])
    res = [[0 for _ in range(c)] for _ in range(l)]
    for i in range(l):
        for j in range(c):
            for k in range(p):
                res[i][j] += A[i][k] * B[k][j]
    return res

