def max_matrice(M, L, C):
    maxi = M[0][0]
    for i in range(L):
        for j in range(C):
            if M[i][j] > maxi:
                maxi = M[i][j]
    return maxi

def moyenne_matrice(M, L, C):
    somme = 0
    for i in range(L):
        for j in range(C):
            somme = somme + M[i][j]
    moy = somme / (L * C)
    return moy

